insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$matinhos$q$, $q$https://www.diariomunicipal.com.br/amp/materia/16396E8B (Decreto 4.604/2025, Diário Oficial dos Municípios do Paraná)$q$, $q$Ato oficial de Matinhos: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 11, $q$Decreto 4.604/2025, art. 5º: o ato diz quando a circulação é PERMITIDA (dias úteis 7h-19h; sáb, dom e feriados 8h-15h); as janelas da regra são o complemento (fora do permitido = restrito), inferência do texto confirmada pelo art. 6º. Feriado em dia útil: o decreto o trata como fim de semana (8h-15h), mais restritivo que a janela de dia útil usada aqui (limitação do formato). Art. 7º permite portarias do Departamento de Trânsito (não localizadas). Matinhos não define VUC nos atos lidos.$q$);
